data.example_webhook_code:
const express = require('express')
const crypto = require('crypto')
const app = express()

app.use(express.json())

const WEBHOOK_SECRET = 'your_signing_secret'

app.post('/webhook', (req, res) => {
  // 1. Verify HMAC signature
  const signature = req.headers['x-webhook-signature']
  const hmac = crypto.createHmac('sha256', WEBHOOK_SECRET)
  hmac.update(JSON.stringify(req.body))
  const expected = hmac.digest('hex')

  if (!crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) {
    return res.status(401).send('Invalid signature')
  }

  // 2. Process based on event type
  const { event, data } = req.body

  switch (event) {
    case 'message.incoming':
      console.log(`Message from ${data.contact.name}: ${data.content}`)
      // Here you can auto-respond, save to DB, etc.
      break
    case 'message.sent':
      console.log(`Message sent: ${data.message_id}`)
      break
    case 'device.disconnected':
      console.log('⚠️ Device disconnected, send alert')
      break
  }

  res.status(200).send('OK')
})

app.listen(3000, () => console.log('Webhook server on port 3000'))
